# -*- coding: utf-8 -*-
"""Lecture 31 vignette pool A -- Pericardial Disease: acute and recurrent
pericarditis, and the adult / elderly care strategies.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Patient vignettes with a varied lead-in (the lead-in decides the answer). Named
findings carry their description in parentheses (cms_e5l31_scope.NAMED). No doses;
anakinra and rilonacept per the 2025 guidance (s35), never "fourth line".
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l31_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


